services = list_services({})
counts = for svc in services {
    res = search_logs({ service: svc, level: "ERROR", page: 1 })
    return {
        service: svc,
        total: res.total_items,
        pages: res.total_pages,
        first_ts: res.items[0].ts if res.items != [] else null,
        last_ts_on_page: res.items[list.length(res.items) - 1].ts if res.items != [] else null
    }
}
best = fold acc = { service: "", total: 0 } for row in counts {
    return row if row.total > acc.total else acc
}
fp = search_logs({ service: best.service, level: "ERROR", page: 1 })
lp = search_logs({ service: best.service, level: "ERROR", page: fp.total_pages })
deploys = get_deploys({ service: best.service })
owner = get_service_owners({ service: best.service })
return { counts, best, first_page_items: fp.items, last_page_items: lp.items, total_pages: fp.total_pages, total_items: fp.total_items, deploys, owner }

